export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
  url: string;
  isDraft: boolean;
}

export interface SiteConfig {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  siteTitle: string;
  siteUrl: string;
  postsPerPage: number;
}

export interface TagInfo {
  name: string;
  pages: Page[];
  count: number;
}

import matter from "gray-matter";
import { readFile } from "node:fs/promises";
import { basename } from "node:path";
import type { Frontmatter } from "./types.js";

export function parseFrontmatter(raw: string): {
  data: Frontmatter;
  content: string;
} {
  const { data, content } = matter(raw);
  return {
    data: data as Frontmatter,
    content,
  };
}

export async function readAndParse(filePath: string): Promise<{
  data: Frontmatter;
  content: string;
  slug: string;
}> {
  const raw = await readFile(filePath, "utf-8");
  const { data, content } = parseFrontmatter(raw);
  const slug = basename(filePath, ".md");
  return { data, content, slug };
}

export function isDraft(data: Frontmatter): boolean {
  return data.draft === true;
}

export function isPublishable(data: Frontmatter): boolean {
  return !isDraft(data);
}

export function hasTitle(data: Frontmatter): boolean {
  return typeof data.title === "string" && data.title.trim().length > 0;
}

export function parseTags(data: Frontmatter): string[] {
  if (!data.tags) return [];
  if (Array.isArray(data.tags)) return data.tags.filter((t): t is string => typeof t === "string").map((t) => t.trim().toLowerCase());
  if (typeof data.tags === "string") return data.tags.split(",").map((t) => t.trim().toLowerCase()).filter((t) => t.length > 0);
  return [];
}

export function parseDate(data: Frontmatter): Date | null {
  if (!data.date) return null;
  const d = new Date(data.date);
  return isNaN(d.getTime()) ? null : d;
}

export function sortByDate<T extends { frontmatter: Frontmatter }>(items: T[], desc = true): T[] {
  return [...items].sort((a, b) => {
    const da = parseDate(a.frontmatter)?.getTime() ?? 0;
    const db = parseDate(b.frontmatter)?.getTime() ?? 0;
    return desc ? db - da : da - db;
  });
}

import hljs from "highlight.js";
import { marked } from "marked";

marked.setOptions({
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      try {
        return hljs.highlight(code, { language: lang }).value;
      } catch {
        // fall through
      }
    }
    return hljs.highlightAuto(code).value;
  },
});

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown, { async: false }) as string;
}

import Handlebars from "handlebars";
import { readFile, readdir, access } from "node:fs/promises";
import { join, relative, dirname, extname } from "node:path";
import type { Page, TagInfo, SiteConfig } from "./types.js";

const templateCache = new Map<string, HandlebarsTemplateDelegate>();

export function registerPartial(name: string, source: string): void {
  Handlebars.registerPartial(name, source);
}

export function registerHelper(name: string, fn: Handlebars.HelperDelegate): void {
  Handlebars.registerHelper(name, fn);
}

export function compile(source: string): HandlebarsTemplateDelegate {
  return Handlebars.compile(source, { noEscape: true });
}

async function readTemplateFile(filePath: string): Promise<string> {
  const cached = templateCache.get(filePath);
  if (cached) return (cached as unknown as string);
  const content = await readFile(filePath, "utf-8");
  templateCache.set(filePath, content as unknown as HandlebarsTemplateDelegate);
  return content;
}

export async function loadPartials(partialsDir: string): Promise<void> {
  try {
    await access(partialsDir);
  } catch {
    return;
  }
  const entries = await readdir(partialsDir, { withFileTypes: true });
  await Promise.all(
    entries
      .filter((e) => e.isFile() && extname(e.name) === ".hbs")
      .map(async (entry) => {
        const name = basename(entry.name, ".hbs") as string;
        const source = await readTemplateFile(join(partialsDir, entry.name));
        registerPartial(name, source);
      })
  );
}

export async function loadTemplate(
  config: SiteConfig,
  name: string
): Promise<HandlebarsTemplateDelegate> {
  const filePath = join(config.templateDir, `${name}.hbs`);
  const cached = templateCache.get(filePath);
  if (cached) return cached;
  const source = await readTemplateFile(filePath);
  const fn = compile(source);
  templateCache.set(filePath, fn);
  return fn;
}

export async function renderPage(
  config: SiteConfig,
  templateName: string,
  data: Record<string, unknown>
): Promise<string> {
  const template = await loadTemplate(config, templateName);
  return template(data);
}

export async function renderAllPages(
  pages: Page[],
  config: SiteConfig,
  tags: TagInfo[]
): Promise<Map<string, string>> {
  const output = new Map<string, string>();
  const publishable = pages.filter((p) => !p.isDraft);
  const sorted = [...publishable].sort(
    (a, b) =>
      new Date(b.frontmatter.date ?? 0).getTime() -
      new Date(a.frontmatter.date ?? 0).getTime()
  );

  const results = await Promise.all([
    ...pages.map(async (page): Promise<[string, string]> => {
      const html = await renderPage(config, "post", {
        ...page.frontmatter,
        content: page.html,
        url: page.url,
        site: {
          title: config.siteTitle,
          url: config.siteUrl,
        },
        pages: publishable,
        tags,
      });
      return [page.url, html];
    }),

    ...(async (): Promise<[string, string][]> => {
      const indexHtml = await renderPage(config, "index", {
        pages: sorted,
        site: { title: config.siteTitle, url: config.siteUrl },
        tags,
      });
      return [["/index.html", indexHtml]];
    })(),

    ...tags.map(async (tag): Promise<[string, string]> => {
      const html = await renderPage(config, "tag", {
        tag,
        pages: tag.pages,
        allTags: tags,
        site: { title: config.siteTitle, url: config.siteUrl },
      });
      return [`/tags/${tag.name}/index.html`, html];
    }),
  ]);

  for (const [url, html] of results) {
    output.set(url, html);
  }

  return output;
}

export function basename(name: string, ext: string): string {
  const idx = name.lastIndexOf(ext);
  return idx >= 0 ? name.slice(0, idx) : name;
}

import type { Page, SiteConfig } from "./types.js";
import { parseDate } from "./frontmatter.js";

export function generateRss(pages: Page[], config: SiteConfig): string {
  const publishable = pages
    .filter((p) => !p.isDraft)
    .sort((a, b) => {
      return (
        (parseDate(b.frontmatter)?.getTime() ?? 0) -
        (parseDate(a.frontmatter)?.getTime() ?? 0)
      );
    });

  const items = publishable
    .map((page) => {
      const date = parseDate(page.frontmatter);
      const rfcDate = date ? date.toUTCString() : new Date().toUTCString();
      return `    <item>
      <title>${escapeXml(page.frontmatter.title)}</title>
      <link>${config.siteUrl}${page.url}</link>
      <guid>${config.siteUrl}${page.url}</guid>
      <pubDate>${rfcDate}</pubDate>
      <description>${escapeXml(page.content.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${config.siteUrl}</link>
    <description>${escapeXml(config.siteTitle)} RSS Feed</description>
    <atom:link href="${config.siteUrl}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>`;
}

function escapeXml(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import type { Page, TagInfo } from "./types.js";
import { parseTags } from "./frontmatter.js";

export function buildTagIndex(pages: Page[]): TagInfo[] {
  const tagMap = new Map<string, Page[]>();

  for (const page of pages) {
    if (page.isDraft) continue;
    const tags = parseTags(page.frontmatter);
    for (const tag of tags) {
      const list = tagMap.get(tag) ?? [];
      list.push(page);
      tagMap.set(tag, list);
    }
  }

  const result: TagInfo[] = [];
  for (const [name, tagPages] of tagMap) {
    tagPages.sort(
      (a, b) =>
        new Date(b.frontmatter.date ?? 0).getTime() -
        new Date(a.frontmatter.date ?? 0).getTime()
    );
    result.push({ name, pages: tagPages, count: tagPages.length });
  }

  result.sort((a, b) => b.count - a.count);
  return result;
}

import { readdir, mkdir, writeFile, access } from "node:fs/promises";
import { join, relative, extname, dirname } from "node:path";
import type { Page, SiteConfig, TagInfo } from "./types.js";
import { readAndParse, isDraft, parseTags, parseDate } from "./frontmatter.js";
import { markdownToHtml } from "./highlight.js";
import { loadPartials, renderAllPages } from "./renderer.js";
import { generateRss } from "./rss.js";
import { buildTagIndex } from "./tags.js";

export async function discoverMarkdownFiles(
  dir: string
): Promise<string[]> {
  const results: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true });
  await Promise.all(
    entries.map(async (entry) => {
      const fullPath = join(dir, entry.name);
      if (entry.isDirectory()) {
        const sub = await discoverMarkdownFiles(fullPath);
        results.push(...sub);
      } else if (entry.isFile() && extname(entry.name) === ".md") {
        results.push(fullPath);
      }
    })
  );
  return results;
}

export async function generate(config: SiteConfig): Promise<void> {
  await mkdir(config.outputDir, { recursive: true });

  await loadPartials(join(config.templateDir, "partials"));

  const files = await discoverMarkdownFiles(config.sourceDir);

  const pages: Page[] = await Promise.all(
    files.map(async (filePath) => {
      const rel = relative(config.sourceDir, filePath);
      const { data, content, slug } = await readAndParse(filePath);
      const html = markdownToHtml(content);
      const parentDir = dirname(rel);
      const url =
        parentDir === "."
          ? `/${slug}/index.html`
          : `/${parentDir}/${slug}/index.html`;

      return {
        path: filePath,
        frontmatter: data,
        content,
        html,
        url,
        isDraft: isDraft(data),
      };
    })
  );

  const tags = buildTagIndex(pages);
  const output = await renderAllPages(pages, config, tags);

  for (const [url, html] of output) {
    const outPath = join(config.outputDir, url);
    await mkdir(dirname(outPath), { recursive: true });
    await writeFile(outPath, html, "utf-8");
  }

  const rss = generateRss(pages, config);
  await writeFile(join(config.outputDir, "rss.xml"), rss, "utf-8");
}

