import http from "node:http";
import { readFile, access } from "node:fs/promises";
import { join, extname } from "node:path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import type { SiteConfig } from "./types.js";
import { generate } from "./generator.js";

const RELOAD_SCRIPT = `
<script>
(function() {
  var socket = new WebSocket('ws://' + location.host + '/__ssg_reload');
  socket.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  socket.onclose = function() {
    setTimeout(function() {
      location.reload();
    }, 2000);
  };
})();
</script>`;

function injectReloadScript(html: string): string {
  if (html.includes("</body>")) {
    return html.replace("</body>", RELOAD_SCRIPT + "</body>");
  }
  return html + RELOAD_SCRIPT;
}

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".xml": "application/xml",
  ".woff2": "font/woff2",
};

export async function startDevServer(config: SiteConfig, port = 3000): Promise<http.Server> {
  let wss: WebSocketServer;
  let clients = new Set<WebSocket>();

  await generate(config);

  const server = http.createServer(async (req, res) => {
    const url = req.url ?? "/";
    const filePath =
      url === "/" || url.endsWith("/")
        ? join(config.outputDir, url, "index.html")
        : join(config.outputDir, url);

    try {
      await access(filePath);
      const content = await readFile(filePath);
      const ext = extname(filePath);
      const contentType = MIME_TYPES[ext] ?? "application/octet-stream";
      res.writeHead(200, { "Content-Type": contentType });

      if (ext === ".html" || filePath.endsWith("/index.html")) {
        res.end(injectReloadScript(content.toString()));
      } else {
        res.end(content);
      }
    } catch {
      res.writeHead(200, { "Content-Type": "text/html" });
      const indexPath = join(config.outputDir, "index.html");
      try {
        await access(indexPath);
        const html = await readFile(indexPath, "utf-8");
        res.end(injectReloadScript(html));
      } catch {
        res.writeHead(404);
        res.end("Not found");
      }
    }
  });

  wss = new WebSocketServer({ server, path: "/__ssg_reload" });

  wss.on("connection", (ws) => {
    clients.add(ws);
    ws.on("close", () => clients.delete(ws));
  });

  const broadcast = () => {
    const msg = JSON.stringify("reload");
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  };

  const watcher = chokidar.watch(
    [config.sourceDir, config.templateDir],
    {
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 50 },
    }
  );

  let rebuildTimer: ReturnType<typeof setTimeout> | null = null;

  watcher.on("all", async () => {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(async () => {
      try {
        await generate(config);
        broadcast();
      } catch (err) {
        console.error("Build error:", err);
      }
    }, 100);
  });

  return new Promise((resolve) => {
    server.listen(port, () => {
      console.log(`Dev server running at http://localhost:${port}`);
      resolve(server);
    });
  });
}

import { Command } from "commander";
import { resolve } from "node:path";
import { generate } from "./generator.js";
import { startDevServer } from "./dev-server.js";
import type { SiteConfig } from "./types.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator from Markdown files")
  .version("1.0.0")
  .option("-s, --source <dir>", "Source directory of Markdown files", "./content")
  .option("-t, --templates <dir>", "Template directory of Handlebars templates", "./templates")
  .option("-o, --output <dir>", "Output directory for generated site", "./dist-site")
  .option("--title <title>", "Site title", "My Site")
  .option("--url <url>", "Site URL for RSS feed", "http://localhost:3000")
  .option("--posts-per-page <n>", "Posts per page", "10");

function buildConfig(opts: Record<string, unknown>): SiteConfig {
  const sourceDir = resolve(String(opts.source ?? "./content"));
  const templateDir = resolve(String(opts.templates ?? "./templates"));
  const outputDir = resolve(String(opts.output ?? "./dist-site"));
  const siteTitle = String(opts.title ?? "My Site");
  const siteUrl = String(opts.url ?? "http://localhost:3000");
  const postsPerPage = parseInt(String(opts.postsPerPage ?? "10"), 10);

  return { sourceDir, templateDir, outputDir, siteTitle, siteUrl, postsPerPage };
}

program
  .command("build", { isDefault: true })
  .description("Build the static site")
  .action(async (opts) => {
    const parent = program.opts();
    const config = buildConfig(parent);
    console.log("Building site...");
    await generate(config);
    console.log(`Site built to ${config.outputDir}`);
  });

program
  .command("serve")
  .description("Start development server with live reload")
  .option("-p, --port <port>", "Port to listen on", "3000")
  .action(async (opts) => {
    const parent = program.opts();
    const config = buildConfig(parent);
    const port = parseInt(String(opts.port ?? "3000"), 10);
    await startDevServer(config, port);
  });

export default program;

#!/usr/bin/env node
import program from "./cli.js";

program.parse(process.argv);

import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import type { SiteConfig } from "../src/types.js";

const __dirname = dirname(fileURLToPath(import.meta.url));

export const fixturesDir = resolve(__dirname, "fixtures");

export function makeConfig(overrides?: Partial<SiteConfig>): SiteConfig {
  return {
    sourceDir: resolve(fixturesDir, "content"),
    templateDir: resolve(fixturesDir, "templates"),
    outputDir: resolve(fixturesDir, "output"),
    siteTitle: "Test Site",
    siteUrl: "http://localhost:3000",
    postsPerPage: 10,
    ...overrides,
  };
}

import { describe, it, expect } from "vitest";
import {
  parseFrontmatter,
  isDraft,
  isPublishable,
  parseTags,
  parseDate,
  sortByDate,
  hasTitle,
} from "../src/frontmatter.js";

describe("parseFrontmatter", () => {
  it("parses YAML frontmatter and content", () => {
    const input = `---
title: Test
tags: [a, b]
---
Content here`;

    const { data, content } = parseFrontmatter(input);
    expect(data.title).toBe("Test");
    expect(data.tags).toEqual(["a", "b"]);
    expect(content.trim()).toBe("Content here");
  });

  it("handles empty frontmatter", () => {
    const input = `---
---
Content`;

    const { data, content } = parseFrontmatter(input);
    expect(content.trim()).toBe("Content");
    expect(data.title).toBeUndefined();
  });

  it("handles no frontmatter at all", () => {
    const input = "Just content";
    const { data, content } = parseFrontmatter(input);
    expect(content.trim()).toBe("Just content");
    expect(data.title).toBeUndefined();
  });

  it("parses date from frontmatter", () => {
    const input = `---
date: 2024-01-15
---
content`;

    const { data } = parseFrontmatter(input);
    expect(data.date).toBeDefined();
  });

  it("parses draft boolean", () => {
    const input = `---
draft: true
---
content`;

    const { data } = parseFrontmatter(input);
    expect(data.draft).toBe(true);
  });
});

describe("isDraft / isPublishable", () => {
  it("returns true for draft: true", () => {
    expect(isDraft({ title: "x", draft: true })).toBe(true);
  });

  it("returns false when draft is false", () => {
    expect(isDraft({ title: "x", draft: false })).toBe(false);
  });

  it("returns false when draft is not set", () => {
    expect(isDraft({ title: "x" })).toBe(false);
  });

  it("isPublishable is the inverse", () => {
    expect(isPublishable({ title: "x", draft: true })).toBe(false);
    expect(isPublishable({ title: "x" })).toBe(true);
  });
});

describe("hasTitle", () => {
  it("returns true for valid title", () => {
    expect(hasTitle({ title: "Hello" })).toBe(true);
  });

  it("returns false for empty string", () => {
    expect(hasTitle({ title: "" })).toBe(false);
  });

  it("returns false for missing title", () => {
    expect(hasTitle({})).toBe(false);
  });
});

describe("parseTags", () => {
  it("parses array of tags", () => {
    expect(parseTags({ tags: ["foo", "BAR"] })).toEqual(["foo", "bar"]);
  });

  it("parses comma-separated string", () => {
    expect(parseTags({ tags: "foo, bar, baz" })).toEqual(["foo", "bar", "baz"]);
  });

  it("returns empty array when no tags", () => {
    expect(parseTags({})).toEqual([]);
  });

  it("returns empty array for empty tags", () => {
    expect(parseTags({ tags: [] })).toEqual([]);
  });

  it("filters non-string entries", () => {
    expect(parseTags({ tags: ["foo", 123, "bar"] as unknown[] } as any)).toEqual(["foo", "bar"]);
  });
});

describe("parseDate", () => {
  it("parses valid date string", () => {
    const d = parseDate({ date: "2024-01-15" });
    expect(d).toBeInstanceOf(Date);
    expect(d!.getFullYear()).toBe(2024);
  });

  it("returns null for missing date", () => {
    expect(parseDate({})).toBeNull();
  });

  it("returns null for invalid date string", () => {
    expect(parseDate({ date: "not-a-date" })).toBeNull();
  });
});

describe("sortByDate", () => {
  it("sorts descending by default", () => {
    const items = [
      { frontmatter: { date: "2024-01-01" } },
      { frontmatter: { date: "2024-03-01" } },
      { frontmatter: { date: "2024-02-01" } },
    ];
    const sorted = sortByDate(items);
    expect(sorted[0].frontmatter.date).toBe("2024-03-01");
    expect(sorted[2].frontmatter.date).toBe("2024-01-01");
  });

  it("sorts ascending when desc=false", () => {
    const items = [
      { frontmatter: { date: "2024-03-01" } },
      { frontmatter: { date: "2024-01-01" } },
    ];
    const sorted = sortByDate(items, false);
    expect(sorted[0].frontmatter.date).toBe("2024-01-01");
  });
});

import { describe, it, expect, beforeAll } from "vitest";
import { compile, loadTemplate, renderPage, loadPartials } from "../src/renderer.js";
import { makeConfig } from "./helpers.js";
import Handlebars from "handlebars";

describe("compile", () => {
  it("compiles a Handlebars template", () => {
    const tpl = compile("Hello {{name}}");
    expect(tpl({ name: "World" })).toBe("Hello World");
  });

  it("renders with HTML escaping when needed", () => {
    const tpl = compile("Escaped: {{value}}");
    expect(tpl({ value: "<script>" })).toBe("Escaped: &lt;script&gt;");
  });
});

describe("loadPartials", () => {
  it("loads partials from directory", async () => {
    const config = makeConfig();
    await loadPartials(config.templateDir + "/partials");
    const partials = Handlebars.partials;
    expect(partials["header"]).toBeDefined();
    expect(partials["footer"]).toBeDefined();
  });
});

describe("loadTemplate", () => {
  it("loads and caches a template from disk", async () => {
    const config = makeConfig();
    const tpl = await loadTemplate(config, "post");
    const result = tpl({ title: "Test", date: "2024-01-01", content: "<p>Hello</p>" });
    expect(result).toContain("Test");
    expect(result).toContain("2024-01-01");
